#pragma once
std::wstring productName(const fs::path&);
std::wstring normalizedApplicationName(std::wstring name){name=lower(name);for(auto word:{L"(64-bit)",L"(32-bit)",L"(x64)",L"(x86)",L"(user)",L"adobe ",L"microsoft ",L"google ",L"mozilla "}){size_t pos;while((pos=name.find(word))!=std::wstring::npos)name.erase(pos,wcslen(word));}std::wstring result;for(auto c:name)if(iswalpha(c))result+=c;return result;}
bool applicationNameMatches(const std::wstring&a,const std::wstring&b){auto first=normalizedApplicationName(a),second=normalizedApplicationName(b);return first.size()>=4&&first==second;}
bool plausibleApplicationRoot(const fs::path& path){if(!path.is_absolute()||path==path.root_path())return false;auto text=lower(path.wstring());for(auto part:{L"windows",L"program files",L"program files (x86)",L"common files",L"users",L"installer"})if(lower(path.filename().wstring())==part)return false;return text.find(L"windows\\installer")==std::wstring::npos;}
void resolveRegisteredPath(Entry&e){std::error_code ec;if(!e.path.empty()&&fs::is_directory(e.path,ec)){e.locationSource=L"注册表安装信息";return;}
 std::vector<std::wstring> candidates;auto icon=e.iconPath;if(!icon.empty()){auto comma=icon.rfind(L',');if(comma!=std::wstring::npos)icon.resize(comma);candidates.push_back(clean(icon));}
 for(auto command:{e.uninstallCommand,e.quietUninstallCommand}){if(command.empty())continue;if(command.front()==L'"'){auto end=command.find(L'"',1);if(end!=std::wstring::npos)candidates.push_back(command.substr(1,end-1));}else{auto end=lower(command).find(L".exe");if(end!=std::wstring::npos)candidates.push_back(command.substr(0,end+4));}}
 for(auto&candidate:candidates){fs::path file(candidate);if(!file.is_absolute()||!fs::is_regular_file(file,ec))continue;auto base=lower(file.filename().wstring());if(lower(file.extension().wstring())==L".exe"&&base.find(L"uninstall")==std::wstring::npos&&base.find(L"setup")==std::wstring::npos&&plausibleApplicationRoot(file.parent_path())&&applicationNameMatches(productName(file),e.name)){e.path=file.parent_path().wstring();e.iconPath=file.wstring();e.locationSource=L"主程序产品信息匹配";return;}
 auto dir=file.parent_path();for(int level=0;level<6&&!dir.empty();level++){if(plausibleApplicationRoot(dir)&&applicationNameMatches(dir.filename().wstring(),e.name)){e.path=dir.wstring();e.locationSource=L"已存在的图标 / 卸载路径与应用目录名称匹配";return;}auto parent=dir.parent_path();if(parent==dir)break;dir=parent;}}
 e.path=L"尚未定位（待深度扫描确认）";e.locationSource=L"未确认，不能作为删除范围";
}

bool diskProgramMatchesRegistration(const Entry&e,const fs::path& file){if(!applicationNameMatches(productName(file),e.name))return false;if(e.version.empty())return true;DWORD ignored=0,size=GetFileVersionInfoSizeW(file.c_str(),&ignored);if(!size||size>4*1024*1024)return false;std::vector<BYTE> data(size);if(!GetFileVersionInfoW(file.c_str(),0,size,data.data()))return false;VS_FIXEDFILEINFO* info=nullptr;UINT length=0;if(!VerQueryValueW(data.data(),L"\\",(void**)&info,&length)||length<sizeof(VS_FIXEDFILEINFO))return false;std::wstring actual=std::to_wstring(HIWORD(info->dwFileVersionMS))+L"."+std::to_wstring(LOWORD(info->dwFileVersionMS))+L"."+std::to_wstring(HIWORD(info->dwFileVersionLS))+L"."+std::to_wstring(LOWORD(info->dwFileVersionLS));std::wstring expected;for(auto c:e.version){if(iswdigit(c)||c==L'.')expected+=c;else if(!expected.empty())break;}while(!expected.empty()&&expected.back()==L'.')expected.pop_back();return !expected.empty()&&(actual==expected||(actual.size()>expected.size()&&actual.compare(0,expected.size(),expected)==0&&actual[expected.size()]==L'.'));}
